const names=['antilink','antiinvite','antispam','antiflood','anticaps','antiemoji','antitag','antiword','antiscam','antiphishing','antirepeat','antilongtext','antiunicode','antiforward','antimedia','antiimage','antivideo','antiaudio','antisticker','antidocument','anticontact','antilocation','antipoll','antiviewonce','antibot','antinsfw','antistatus','anticall','antidisappearing','antighost'];
const aliases={antilink:['al'],antiinvite:['aii'],antispam:['as'],antiflood:['af'],antitag:['atag'],antiword:['aword'],anticall:['acall']};
function make(name){return {name,alias:aliases[name]||[],category:'Defense',desc:`Configure ${name} protection for this group`,usage:`.${name} on|off|status`,groupOnly:true,adminOnly:true,execute:async(s,m,{args,reply,store})=>{const g=store.group(m.chat);const v=String(args[0]||'status').toLowerCase();if(v==='on'||v==='off')g[name]=v==='on';store.save();return reply(`🛡️ ${name}: ${g[name]?'ON':'OFF'}\nUse .${name} on/off/status.`)}}}
module.exports=names.map(make);
